window.BALTI_DATA={overview:{title:"Balti Language Explorer",nativePersoArabic:"بلتی زبان",nativeTibetan:"སྦལ་ཏིའི་སྐད།",family:"Sino-Tibetan ➔ Tibeto-Burman ➔ Bodish ➔ Western Archaic Tibetan",speakers:"400,000+ (India & High Himalayas)",primaryRegions:["Kargil District","Turtuk / Tyakshi / Thang (Nubra Valley, Leh)","Chorbat Valley","Baltistan Region"],writingScripts:["Perso-Arabic (Nastaliq)","Tibetan (Yag-mo)","Yek-mo (Ancient)"],description:"Balti is a prized Western Archaic Tibetan language spoken in the high valleys of Ladakh (Kargil, Turtuk, Nubra) and Baltistan. Remarkable for preserving the 7th-century Old Tibetan initial consonant clusters that were lost in Lhasa Tibetan, Balti represents a living linguistic bridge across Himalayan history."},genealogy:{root:"Proto-Sino-Tibetan",branch:"Tibeto-Burman ➔ Bodish",subgroup:"Western Archaic Tibetan (Balti-Ladakhi)",characteristics:[{title:"Preservation of Old Tibetan Consonants",desc:"Balti retains complex 7th-century Old Tibetan initial consonant clusters like 'zla-' (moon), 'rg-', 'st-', and 'dby-' which became silent or tone markers in Lhasa Tibetan."},{title:"Non-Tonal / Pitch Accent",desc:"Unlike Central Lhasa Tibetan which developed a strict tonal system, Balti remains non-tonal or relies on subtle pitch accent patterns."},{title:"Suffixal Ergativity & Verb Morphology",desc:"Nouns take ergative markers ('-syis' / '-is') while verbs use rich auxiliary suffixes to denote evidentiality and aspect."},{title:"Persian & Arabic Lexical Synthesis",desc:"Centuries of cultural exchange introduced Persian and Arabic loanwords alongside core Tibetic vocabulary, especially in poetry and administration."}]},scripts:[{name:"Perso-Arabic Script (Nastaliq)",native:"بلتی رسم الخط",status:"Primary Written Script in Modern Era",desc:"Adopted after the introduction of Islam in the 14th–15th centuries. Written right-to-left in elegant Nastaliq style with special modified letters (like ݗ for 'x' and ݖ for 'ch') to accommodate Tibetic phonemes.",example:"بلتی زبان بچھایدوک"},{name:"Tibetan Script (Yag-mo / Uchen)",native:"སྦལ་ཏིའི་ཡི་གེ",status:"Historical & Modern Cultural Revival",desc:"The classical script of Baltistan used until the 16th century. Currently undergoing a vibrant cultural revival in Ladakh and Kargil for printing Balti poetry, signboards, and educational literature.",example:"སྦལ་ཏིའི་སྐད་ཁམས་ཟང་ཡོད།"},{name:"Yek-mo Script (Indigenous)",native:"ཡེག་མོ།",status:"Historical Indigenous Script",desc:"An ancient script indigenous to Baltistan documented on ancient stone carvings and royal decrees prior to the widespread adoption of Tibetan and Arabic scripts.",example:"Ancient Petroglyph Symbolism"}],regions:[{id:"kargil",name:"Kargil District",subRegions:["Hardass","Sod","Batalik","Pashkum","Kargil Town"],speakers:"approx. 120,000",color:"#06b6d4",desc:"Major cultural epicentre of Balti speakers in Ladakh. Hardass village is renowned for its world-famous sweet apricots (Chuli) and preserved Balti songs."},{id:"turtuk",name:"Turtuk & Tyakshi (Nubra Valley)",subRegions:["Turtuk","Tyakshi","Thang","Chulunkha"],speakers:"approx. 10,000",color:"#f59e0b",desc:"Located on the banks of the Shyok River in Leh district, Turtuk is India's northernmost Balti village, famous for unique wooden architecture, Balti polo, and apricot gardens."},{id:"chorbat",name:"Chorbat Valley",subRegions:["Bogdang","Chorbat","Dah-Hanu border"],speakers:"approx. 15,000",color:"#10b981",desc:"High Himalayan valley connecting Kargil and Nubra, where Balti and Ladakhi cultural traditions blend seamlessly."},{id:"leh",name:"Leh & Suburban Settlements",subRegions:["Choglamsar","Leh City","Saboo"],speakers:"approx. 8,000",color:"#8b5cf6",desc:"Vibrant Balti diaspora and trader community living alongside Ladakhi and Zanskari speakers in Leh town."}],greetings:[{id:"juleh",category:"Universal Greeting",persoArabic:"جولے / خمزانگ",tibetan:"ཇུ་ལེ། / ཁམས་ཟང་།",transliteration:"Ju-leh / Khamzang",ipa:"[dʑule / kʰamzaŋ]",meaning:"Hello / Greetings / Welcome / Peace be upon you",phoneticSynth:"Joo-leh Khahm-zahng",note:"The signature Himalayan greeting used across Ladakh and Baltistan expressing deep respect."},{id:"salam",category:"Formal Greeting",persoArabic:"السلام علیکم",tibetan:"ཨས་ས་ལམ་ ཨ་ལཡེ་ཀུམ།",transliteration:"As-salamu alaykum",ipa:"[as.sa.laːmu ʕa.lai.kum]",meaning:"Peace be upon you",phoneticSynth:"Ahs-sah-lah-moo ah-lay-koom",note:"Traditional Islamic greeting widely used in Balti Muslim communities."},{id:"khamzang-yod",category:"How are you?",persoArabic:"چی خمزانگ یودپا؟",tibetan:"ཁྱེད་ཁམས་ཟང་ཡོད་པ།",transliteration:"Khyed khamzang yod-pa?",ipa:"[kʰjed kʰamzaŋ jodpa]",meaning:"Are you doing well in health and spirit?",phoneticSynth:"Khyed khahm-zahng yohd-pah",note:"Polite inquiry into well-being."},{id:"shukriya",category:"Thank You",persoArabic:"شکریہ / جولے",tibetan:"ཤུཀ་རི་ཡ། / ཇུ་ལེ།",transliteration:"Shukriya / Ju-leh",ipa:"[ʃukriːaː / dʑule]",meaning:"Thank you very much / Deep gratitude",phoneticSynth:"Shook-ree-yah Joo-leh",note:"Used to express heartfelt gratitude for hospitality."},{id:"khuda-hafiz",category:"Farewell",persoArabic:"خدا حافظ / جولے",tibetan:"ཁུ་དཱ་ ཧཱ་ཕིཟ། / ཇུ་ལེ།",transliteration:"Khuda hafiz / Ju-leh",ipa:"[xudaː haːfiz / dʑule]",meaning:"May God protect you / Goodbye",phoneticSynth:"Khoo-dah Hah-feez Joo-leh",note:"Warm departure blessing wished to travelers."}],vocabularyMatrix:[{concept:"Water",persoArabic:"چھو",tibetan:"ཆུ།",transliteration:"Chhu",ipa:"/tɕʰu/",oldTibetan:"ཆུ (Chhu)",etymology:"Direct preservation of Old Tibetan root for glacial mountain water."},{concept:"Fire",persoArabic:"می",tibetan:"མེ།",transliteration:"Me",ipa:"/me/",oldTibetan:"མེ (Me)",etymology:"Core Tibetic root conserved across high Himalayan dialects."},{concept:"Sun",persoArabic:"نیما",tibetan:"ཉི་མ།",transliteration:"Nima",ipa:"/ɲima/",oldTibetan:"ཉི་མ (Nyi-ma)",etymology:"Denotes both physical sun and daylight."},{concept:"Moon",persoArabic:"زلاوا / تمگس",tibetan:"ཟླ་བ།",transliteration:"Zlawa / Tamgas",ipa:"/zlawa/",oldTibetan:"ཟླ་བ (Zla-ba)",etymology:"Linguistic Marvel: Balti preserves the initial 'Zl-' consonant cluster (Zlawa), whereas Lhasa Tibetan lost 'z' and pronounces it simply as 'Dawa'."},{concept:"Eye",persoArabic:"مگ",tibetan:"མིག།",transliteration:"Mik",ipa:"/mik/",oldTibetan:"མིག (Mig)",etymology:"Preserves the final unvoiced stop '-k'."},{concept:"House",persoArabic:"کھنگپا",tibetan:"ཁང་པ།",transliteration:"Khang-pa",ipa:"/kʰaŋpa/",oldTibetan:"ཁང་པ (Khang-pa)",etymology:"Standard Tibetic dwelling noun."},{concept:"Mountain",persoArabic:"ری",tibetan:"རི།",transliteration:"Ri",ipa:"/ri/",oldTibetan:"རི (Ri)",etymology:"Refers to high mountain peaks and mountain ranges."},{concept:"Friend / Companion",persoArabic:"چھوس / دوست",tibetan:"གྲོགས་པོ། / ཆོས།",transliteration:"Chhos / Groks-po",ipa:"[tɕʰos / ɡrokspo]",oldTibetan:"གྲོགས་པོ (Groks-po)",etymology:"Balti retains the unsimplified 'gr-' prefix sound in traditional speech."},{concept:"Good / Well",persoArabic:"خمزانگ / لایمو",tibetan:"ཁམས་ཟང་། / ལེགས་པོ།",transliteration:"Khamzang / Laymo",ipa:"/kʰamzaŋ / laimo/",oldTibetan:"ཁམས་ཟང་ (Kham-zang)",etymology:"Compound of 'Kham' (health/element) + 'Zang' (good)."},{concept:"Apricot",persoArabic:"چولی",tibetan:"ཅུ་ལི།",transliteration:"Chuli",ipa:"/tɕuli/",oldTibetan:"ཅུ་ལི (Chuli)",etymology:"Iconic Balti word for the prized sweet apricot varieties of Hardass & Turtuk."}],culturalHeritage:[{title:"Balti Sufi Ghazals & Poetry",category:"Literature & Music",icon:"📜",content:"Balti literature boasts a magnificent poetic tradition featuring Ghazals, Kasidas, and Marsiyas. Renowned poets like Sangee Ali Khan and Baba Lobsang Sangee composed soulful lyrics blending Tibetic meters with Persian poetic forms."},{title:"Royal Balti Polo (Raja Polo)",category:"High-Altitude Sports",icon:"🐎",content:"Polo in Baltistan and Turtuk is not merely a sport—it is a sacred royal festival. Played on natural grass grounds to the fast-paced, hypnotic rhythm of Surna (oboe) and Daman (kettledrums)."},{title:"Apricot Orchard Culture (Chuli)",category:"Agriculture & Cuisine",icon:"🍑",content:"Turtuk and Hardass in Kargil produce some of the sweetest apricots in the world (Halman & Raktsey Karpo varieties). Apricot kernel oil and dried fruit are staples of Balti hospitality."},{title:"Traditional Attire (Khos & Tipi)",category:"Material Culture",icon:"🧥",content:"Men wear the 'Khos'—a thick, hand-spun wool gown bound with a sash—along with a distinctive woolen Balti cap ('Tipi') decorated with fresh flowers or peacock feathers during festivities."}],quizQuestions:[{question:"Why is Balti considered a 'Linguistic Marvel' among Tibetic languages?",options:["It preserves 7th-century Old Tibetan consonant clusters like 'Zlawa' for Moon","It uses Latin script exclusively","It has no vowels","It was created in the 20th century"],correct:0,explanation:"Balti preserves ancient Old Tibetan initial consonant clusters (such as 'Zla-' in Zlawa for Moon) which were lost in Lhasa Tibetan."},{question:"Which northernmost Indian village in Nubra Valley, Ladakh is famous for its Balti culture and apricot orchards?",options:["Turtuk","Gulmarg","Manali","Dharamshala"],correct:0,explanation:"Turtuk (along with Tyakshi and Thang) in Nubra valley, Ladakh is India's northernmost Balti village."},{question:"What is the universal respectful greeting used across Ladakh and Baltistan?",options:["Ju-leh!","Namaste!","Vanakkam!","Sat Sri Akal!"],correct:0,explanation:"Ju-leh! (or Ju-leh / Khamzang) is the signature respectful greeting across Ladakh and Baltistan."},{question:"What is the Balti word for the famous sweet apricots grown in Kargil and Turtuk?",options:["Chuli","Seb","Aam","Kaju"],correct:0,explanation:"'Chuli' is the authentic Balti word for sweet apricots."},{question:"Which three writing systems are associated with Balti history and modern revival?",options:["Perso-Arabic (Nastaliq), Tibetan (Yag-mo), and Yek-mo","Devanagari, Cyrillic, and Greek","Hieroglyphics, Cuneiform, and Brahmi","Runic, Ogham, and Hebrew"],correct:0,explanation:"Balti heritage is recorded in Perso-Arabic Nastaliq, Classical Tibetan (Yag-mo), and ancient Yek-mo scripts."}]};